#!/usr/bin/env python3
"""P22-10: tables generated ONLY from immutable raw experiment outputs under results/v2/<id>/result.json (+ their SHA-256). Hand-edited numbers cannot enter; `--check` fails if the doc differs."""
import hashlib, json, sys
from pathlib import Path
REPO = Path(__file__).resolve().parents[1]; IDS = ["p14-parity", "p15-delegation", "p16-epistemic", "p17-transactions", "p18-memory", "p19-attestation", "p20-least-privilege", "p21-arena", "p22-selective"]


def build():
    md = ["# Advanced-phase tables (generated by scripts/paper_tables.py from results/v2/*/result.json)", ""]; src = {}
    for i in IDS:
        f = REPO / "results/v2" / i / "result.json"; raw = f.read_bytes(); src[i] = hashlib.sha256(raw).hexdigest(); d = json.loads(raw)
        if i == "p14-parity": md += ["## P14 parity (workflows vs MCP-modern reference)", "", "| path | verdict agree | effect agree | total |", "|---|---|---|---|"] + [f"| {p} | {c['verdict_agree']} | {c['effect_agree']} | {c['total']} |" for p, c in d["coverage"].items()]
        if i == "p15-delegation": md += ["", "## P15 delegation (synthetic)", "", "| system | legit completed | unauthorized allowed |", "|---|---|---|"] + [f"| {k} | {v['legit_completed']}/{v['legit_total']} | {v['unauthorized_allowed']}/{v['unauthorized_total']} |" for k, v in d.items()]
        if i == "p16-epistemic": md += ["", "## P16 epistemic (author-built fixtures)", "", "| system | harm allowed | false blocks |", "|---|---|---|"] + [f"| {k} | {v['harm_allowed']}/{v['harmful_cases']} | {v['false_blocks']}/{v['benign_cases']} |" for k, v in d["deployable"].items()]
        if i == "p17-transactions": md += ["", "## P17 transactions (synthetic KV)", "", "| system | prevented (verified absent) | residual damage | legit final state correct |", "|---|---|---|---|"] + [f"| {k} | {v['prevented_verified_absent']}/{v['prohibited_attempts']} | {v['residual_damage']} | {v['legit_final_state_correct']}/{v['legit_total']} |" for k, v in d.items()]
        if i == "p18-memory": md += ["", "## P18 memory (scripted)", "", "| system | missed delayed harms | benign recall blocked |", "|---|---|---|"] + [f"| {k} | {d[k]['missed_delayed_harms']}/{d[k]['harm_scenarios']} | {d[k]['benign_recall_blocked']}/{d[k]['benign_scenarios']} |" for k in ("provenance_memory", "no_provenance", "session_only_taint")]
        if i == "p19-attestation": md += ["", "## P19 drift (10 fixtures)", "", f"- benign usable {d['benign_usable']}/{d['benign_total']}; malicious caught pre-deploy {d['malicious_caught_predeploy']}, runtime-only {d['malicious_caught_runtime_only']}, missed {d['malicious_missed']}; opaque = {d['opaque_status']}"]
        if i == "p20-least-privilege": md += ["", "## P20 least privilege", "", "| system | mean exposure | completed | unauthorized expansions |", "|---|---|---|---|"] + [f"| {k} | {d[k]['mean_exposure']} | {d[k]['completed']} | {d[k]['unauthorized_expansions']} |" for k in ("attenuated_per_task", "static_all_tools", "static_rbac", "heuristic_least_privilege")]
        if i == "p21-arena": md += ["", "## P21 arena (dev / holdout attack success rate, 400-attack budget)", "", "| stack | dev | holdout |", "|---|---|---|"] + [f"| {k} | {v['dev_success_rate']} | {v['holdout_success_rate']} |" for k, v in d["stacks"].items()]
        if i == "p22-selective":
            md += ["", "## P22 selective verification (SIMULATED verifier and reviewer)", "", "| target | policy | harm landed | verifier calls | human reviews | false blocks |", "|---|---|---|---|---|---|"]
            for t, rows in d["targets"].items(): md += [f"| {t} | {p} | {m['harm_landed_rate']} | {m['verifier_calls']} | {m['human_reviews']} | {m['false_blocks']} |" for p, m in rows.items() if "harm_landed_rate" in m]
    md += ["", "## Input hashes (SHA-256)", ""] + [f"- {k}: `{v}`" for k, v in src.items()]
    return "\n".join(md) + "\n"


if __name__ == "__main__":
    out = build(); path = REPO / "docs/evidence/ADVANCED_TABLES.md"
    if "--check" in sys.argv:
        if not path.exists() or path.read_text() != out: print("tables stale"); raise SystemExit(1)
        print("tables up to date")
    else: path.write_text(out); print(out[:600])
